body.script:
function toggleSearch(event) {
  event.preventDefault();
  const box = document.getElementById("searchBox");
  if (box.style.display === "block") {
    box.style.display = "none";
  } else {
    box.style.display = "block";
    box.querySelector("input").focus();
  }
}
document.addEventListener("DOMContentLoaded", function() {
  var btn = document.querySelector(".eisa-search-btn");
  if (btn) btn.addEventListener("click", toggleSearch);
});

b:if.script:
//
(function(){
  /* Ασφάλεια: σε σελίδες άρθρου/page φορτώνεται το MathJax — εκεί ΔΕΝ κάνουμε κανέναν καθαρισμό. */
  if (window.MathJax) { return; }
  var MAP = {
    '\\times':'×','\\cdot':'·','\\div':'÷','\\pm':'±','\\mp':'∓',
    '\\leq':'≤','\\le':'≤','\\geq':'≥','\\ge':'≥','\\neq':'≠','\\ne':'≠',
    '\\approx':'≈','\\equiv':'≡','\\infty':'∞','\\sqrt':'√','\\sum':'∑','\\int':'∫',
    '\\alpha':'α','\\beta':'β','\\gamma':'γ','\\delta':'δ','\\theta':'θ',
    '\\lambda':'λ','\\mu':'μ','\\pi':'π','\\sigma':'σ','\\phi':'φ','\\omega':'ω',
    '\\rightarrow':'→','\\to':'→','\\leftarrow':'←','\\Rightarrow':'⇒',
    '\\ldots':'…','\\dots':'…','\\cdots':'⋯'
  };
  var SUP = {'0':'⁰','1':'¹','2':'²','3':'³','4':'⁴','5':'⁵','6':'⁶','7':'⁷','8':'⁸','9':'⁹','n':'ⁿ','+':'⁺','-':'⁻'};
  function clean(t){
    if(!t) return t;
    if(t.indexOf('\\')===-1 && t.indexOf('$')===-1) return t;
    t = t.replace(/\$\$?/g,'').replace(/\\[\(\)\[\]]/g,'');
    t = t.replace(/\\frac\s*\{([^{}]*)\}\s*\{([^{}]*)\}/g,'$1/$2');
    t = t.replace(/\^\{([^{}]+)\}/g, function(_,g){ return g.replace(/./g, function(c){ return SUP[c]||('^'+c); }); });
    t = t.replace(/\^([0-9n+\-])/g, function(_,c){ return SUP[c]||('^'+c); });
    t = t.replace(/\\[a-zA-Z]+/g, function(m){ return (MAP[m]!==undefined)?MAP[m]:''; });
    t = t.replace(/[{}]/g,'');
    return t.replace(/\s{2,}/g,' ').trim();
  }
  function fix(el){
    if(el.children.length===0){ var c=clean(el.textContent); if(c!==el.textContent) el.textContent=c; return; }
    Array.prototype.forEach.call(el.childNodes, function(n){
      if(n.nodeType===3){ var c=clean(n.nodeValue); if(c!==n.nodeValue) n.nodeValue=c; }
    });
  }
  function run(){
    var sel = '.newsit-card .meta h3 a, .newsit-card .meta h3, .newsit-card .snippet, .post-title a, .post-title, .post-snippet';
    document.querySelectorAll(sel).forEach(fix);
  }
  if(document.readyState==='loading'){ document.addEventListener('DOMContentLoaded', run); } else { run(); }
})();
