body.script:
//
document.addEventListener('DOMContentLoaded', function () {
  // Όλες οι περιοχές σώματος ανάρτησης
  var scopes = document.querySelectorAll('.post-body');

  // Τίτλος σελίδας (fallback)
  var og = document.querySelector('meta[property="og:title"]');
  var pageTitle = (og && og.content ? og.content : document.title);
  if (pageTitle) { pageTitle = pageTitle.trim(); }

  Array.prototype.forEach.call(scopes, function (scope) {
    var imgs = scope.querySelectorAll('img');
    Array.prototype.forEach.call(imgs, function (img) {
      // Συμπλήρωση ALT αν λείπει
      var alt = img.getAttribute('alt');
      var hasAlt = alt && alt.trim() !== '';
      if (!hasAlt) {
        var figure = img.closest ? img.closest('figure') : null;
        var figcap = figure ? figure.querySelector('figcaption') : null;
        var caption = (figcap && figcap.innerText) ? figcap.innerText.trim() : '';
        var titleAttr = img.getAttribute('title');
        var fallback = (titleAttr && titleAttr.trim()) || caption || pageTitle || 'image';
        img.setAttribute('alt', fallback);
      }

      // Lazy loading + async decoding
      if (!img.getAttribute('loading'))  img.setAttribute('loading', 'lazy');
      if (!img.getAttribute('decoding')) img.setAttribute('decoding', 'async');

      // Πλήρωση width/height για μείωση CLS
      if (!img.getAttribute('width') && img.naturalWidth)   img.setAttribute('width',  img.naturalWidth);
      if (!img.getAttribute('height') && img.naturalHeight) img.setAttribute('height', img.naturalHeight);

    });
  });
});
