document.addEventListener('DOMContentLoaded', function() {
  var cards = document.querySelectorAll('.newsit-card');
  cards.forEach(function(card) {
    var labelSpan = card.querySelector('.post-label-data');
    if (!labelSpan) return;
    var labelText = labelSpan.textContent.trim();
    if (!labelText) return;
    var thumb = card.querySelector('.thumb');
    if (!thumb) return;
    var badge = document.createElement('span');
    badge.className = 'label-badge';
    badge.textContent = labelText;
    thumb.appendChild(badge);
  });
});

// Ταξινόμηση των ετικετών κατά συχνότητα (μεγαλύτερες πρώτες)
document.addEventListener('DOMContentLoaded', () => {
  const list = document.querySelector('#Label1 ul, .label-list ul, .labels ul');
  if (!list) return;

  const items = Array.from(list.querySelectorAll('li'));

  // Συνάρτηση για να διαβάζει το νούμερο μέσα στις παρενθέσεις (π.χ. "Άλγεβρα (12)")
  const getCount = el => {
    const match = el.textContent.match(/\((\d+)\)/);
    return match ? parseInt(match[1], 10) : 0;
  };

  // Ταξινόμηση φθίνουσα (μεγαλύτερα πρώτα)
  items.sort((a, b) => getCount(b) - getCount(a));

  // Ανακατασκευή της λίστας
  items.forEach(li => list.appendChild(li));
});

document.addEventListener("DOMContentLoaded", function () {
  // 1. Εξαίρεση της ΠΡΩΤΗΣ εικόνας των αναρτήσεων (hero thumbnail)
  try {
    var firstHeroImg = document.querySelector(
      "#Blog1 .blog-posts .post-outer img, #Blog1 .blog-posts article img"
    );
    if (firstHeroImg) {
      firstHeroImg.setAttribute("data-no-lazy", "true");
      firstHeroImg.removeAttribute("loading");
    }
  } catch (e) {}

  // 2. Lazy-loading για ΟΛΕΣ τις υπόλοιπες εικόνες
  var images = document.querySelectorAll("img:not([data-no-lazy])");

  images.forEach(function (img) {
    if (!img.hasAttribute("loading")) {
      img.setAttribute("loading", "lazy");
    }
    img.setAttribute("decoding", "async");

    try {
      var src = img.getAttribute("src");
      if (src && /\/s[0-9]+\//.test(src)) {
        img.setAttribute("src", src.replace(/\/s[0-9]+\//, "/s800/"));
      }
    } catch (e) {}
  });

  // 3. IntersectionObserver για browsers χωρίς καλό native lazy-loading
  if ("IntersectionObserver" in window) {
    let observer = new IntersectionObserver(function (entries, obs) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          let img = entry.target;
          if (img.dataset.src) img.src = img.dataset.src;
          obs.unobserve(img);
        }
      });
    });

    document.querySelectorAll("img[data-src]").forEach(function (img) {
      observer.observe(img);
    });
  }
});

