(function() {
  function removeDuplicates() {
    // Μόνο featured + grid — ΟΧΙ τα label sections (Γρίφοι, Άρθρα)
    var seenUrls = [];

    // Πρώτα μάζεψε URLs από featured + grid (όχι limit-3)
    var mainCards = document.querySelectorAll('.newsit-feature .newsit-card, .newsit-grid:not(.limit-3) .newsit-card');
    mainCards.forEach(function(card) {
      var link = card.querySelector('a.thumb');
      if (!link) return;
      seenUrls.push(link.href);
    });

    // Μετά κρύψε duplicates ΜΟΝΟ μέσα στο featured+grid
    var allMainCards = document.querySelectorAll('.newsit-feature .newsit-card, .newsit-grid:not(.limit-3) .newsit-card');
    var seen = [];
    allMainCards.forEach(function(card) {
      var link = card.querySelector('a.thumb');
      if (!link) return;
      var url = link.href;
      if (seen.indexOf(url) !== -1) {
        card.style.display = 'none';
      } else {
        seen.push(url);
      }
    });
  }

  window.addEventListener('load', removeDuplicates);
})();
