(function(){
  function setActiveMenu() {
    var links = document.querySelectorAll('.newsit-like-menu a');
    var currentPath = location.pathname;
    var m = currentPath.match(/\/search\/label\/([^/]+)/);
    var currentLabel = m ? decodeURIComponent(m[1]) : null;
    links.forEach(function(a) {
      a.classList.remove('active');
      var href = a.getAttribute('href') || '';
      if (currentLabel) {
        var lm = href.match(/\/search\/label\/([^/]+)/);
        if (lm && decodeURIComponent(lm[1]).toLowerCase() === currentLabel.toLowerCase()) {
          a.classList.add('active');
        }
      } else if ((currentPath === '/' || currentPath === '') && (href === '/' || href === '')) {
        a.classList.add('active');
      }
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', setActiveMenu);
  } else {
    setActiveMenu();
  }
})();
