(function() {
  var SHOW = 14;
  var colors = ['#2563eb','#059669','#d97706','#7c3aed','#e11d48','#16a34a','#ea580c','#475569'];
  var widths = [95,90,55,42,28,24,23,15];
  var done = false;

  function initLabels(container) {
    if (done) return;
    var spans = Array.prototype.slice.call(container.querySelectorAll(':scope > span'));
    if (spans.length === 0) return;
    done = true;

    spans.forEach(function(span, i) {
      var c = colors[i % colors.length];
      var w = widths[i] || 8;
      var a = span.querySelector('a');
      if (a) {
        a.style.color = c;
        if (!span.querySelector('.eisa-bar')) {
          var bar = document.createElement('div');
          bar.className = 'eisa-bar';
          bar.style.cssText = 'height:4px;border-radius:4px;background:'+c+';opacity:0.7;margin-top:10px;width:'+w+'%';
          span.appendChild(bar);
        }
      }
      if (i >= SHOW) {
        span.classList.add('lbl-hidden');
        span.dataset.hidden = '1';
      }
    });

    var hidden = spans.filter(function(s) { return s.dataset.hidden; });
    if (hidden.length === 0) return;
    if (container.querySelector('.eisa-view-more-btn')) return;

    var btn = document.createElement('button');
    btn.className = 'eisa-view-more-btn';
    btn.setAttribute('aria-expanded', 'false');
    btn.textContent = 'View more labels (' + hidden.length + ') ▼';
    btn.style.cssText = 'grid-column:1/-1;width:100%;margin-top:4px;padding:10px;background:#fff;border:1.5px solid #ddd;border-radius:8px;font-size:13px;font-weight:700;color:#555;cursor:pointer;text-align:center;';
    var open = false;
    btn.addEventListener('click', function() {
      open = !open;
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
      hidden.forEach(function(s) {
        s.classList[open ? 'remove' : 'add']('lbl-hidden');
      });
      btn.textContent = open ? 'View less labels ▲' : 'View more labels (' + hidden.length + ') ▼';
    });
    var ref = spans[SHOW - 1];
    if (ref && ref.nextSibling) { container.insertBefore(btn, ref.nextSibling); }
    else { container.appendChild(btn); }
  }

  function observe() {
    var container = document.querySelector('.cloud-label-widget-content');
    if (container && container.querySelectorAll(':scope > span').length > 0) {
      initLabels(container);
      return;
    }
    var obs = new MutationObserver(function(m, o) {
      var c = document.querySelector('.cloud-label-widget-content');
      if (c && c.querySelectorAll(':scope > span').length > 0) {
        o.disconnect();
        initLabels(c);
      }
    });
    obs.observe(document.body || document.documentElement, { childList: true, subtree: true });
    setTimeout(function() { obs.disconnect(); }, 15000);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', observe);
  } else {
    observe();
  }
})();
